function renderPayrollFinance(k=kpiData(filterRows())){if(!$('#payrollFinanceCard'))return;const owner=currentUser().role==='owner';$('#payrollFinanceCard').hidden=!owner;const journal=$('#expenseForm')?.closest('.card');if(journal)journal.hidden=!owner;if(!owner)return;renderPendingPayroll();const from=$('#fromDate')?.value||'',to=$('#toDate')?.value||'',reports=uniqueShiftReports(state.shiftReports.filter(r=>!r.closureOnly&&(!from||r.date>=from)&&(!to||r.date<=to))).filter(r=>shiftIntegrity(r)||(r.ownerConfirmed&&r.subjectMemberId)),pay=sum(reports,r=>num(r.salary)),ads=sum(state.expenses.filter(x=>norm(x.category).includes('реклам')),x=>num(x.amount)),external=sum(state.expenses,x=>num(x.amount)),net=k.share-pay-external,by=new Map();for(const r of reports){const who=payrollShiftKey(r),key=who==='sergey'?'Сергей':who==='artem'?'Артём':r.approvedForName||r.shiftName||'Сотрудник';if(!by.has(key))by.set(key,{name:key,shifts:0,pay:0,cash:0,deferred:0,orders:0});const x=by.get(key);x.shifts++;x.pay+=num(r.salary);x.cash+=num(r.cash);x.deferred+=num(r.deferredCash);x.orders+=num(r.orders)}$('#payrollFinanceKpis').innerHTML=`<div><span>Фонд зарплат</span><b>${money(pay)}</b><small>${reports.length} закрытых смен</small></div><div><span>Реклама</span><b>${money(ads)}</b><small>из журнала расходов</small></div><div><span>Прочие расходы</span><b>${money(external-ads)}</b><small>без зарплат</small></div><div class="salary"><span>Чистый результат</span><b>${money(net)}</b><small>касса − зарплаты − расходы</small></div>`;$('#payrollFinanceTable').innerHTML=`<table class="table"><thead><tr><th>Сотрудник</th><th class="num">Смен</th><th class="num">Заказов</th><th class="num">Касса</th><th class="num">Поздняя касса</th><th class="num">Зарплата</th><th class="num">Касса / смену</th></tr></thead><tbody>${[...by.values()].sort((a,b)=>b.pay-a.pay).map(x=>`<tr><td><b>${esc(x.name)}</b></td><td class="num">${x.shifts}</td><td class="num">${x.orders}</td><td class="num">${money(x.cash)}</td><td class="num">${money(x.deferred)}</td><td class="num"><b>${money(x.pay)}</b></td><td class="num">${money(x.cash/x.shifts)}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">Закрытых смен за период пока нет</td></tr>'}</tbody></table>`}/* CRM_END:renderPayrollFinance-b7274f246ed3 */
